// Class names whose meaning or existence differs between Tailwind 3 and 4.
// The package's classes are generated by each app's own Tailwind (owner and
// staff run v3, pupils and super-dashboard v4), so it may only write classes
// that mean the same in both.
export const RULES = [
  { test: /^ring$/, why: 'ring width is 3px in v3 and 1px in v4: write ring-2 (or ring-1)' },
  { test: /^shadow(-sm)?$/, why: 'shadow scale was renamed in v4: use shadow-md or larger' },
  { test: /^rounded(-sm)?$/, why: 'radius scale was renamed in v4: use rounded-md or rounded-lg' },
  { test: /^blur(-sm)?$/, why: 'blur scale was renamed in v4: use blur-md or larger' },
  { test: /^drop-shadow(-sm)?$/, why: 'drop-shadow scale was renamed in v4: use drop-shadow-md or larger' },
  { test: /^(bg|text|border|divide|ring|placeholder)-opacity-/, why: 'removed in v4: use a /50 opacity suffix' },
  { test: /^flex-(grow|shrink)(-|$)/, why: 'removed in v4: use grow / shrink' },
  { test: /^(overflow-ellipsis|decoration-(slice|clone))$/, why: 'removed in v4: use text-ellipsis / box-decoration-*' },
  { test: /^(shadow-xs|rounded-xs|blur-xs|outline-hidden|inset-shadow-.*|text-shadow-.*)$/, why: 'v4 only: not generated by Tailwind 3' },
  { test: /^(animate-in|animate-out|fade-(in|out)(-\d+)?|zoom-(in|out)(-\d+)?|slide-(in|out)-from-.*)$/, why: 'needs tailwindcss-animate (v3) or tw-animate-css (v4): use a CSS transition' },
  { test: /^!|!$/, why: 'important moved from a ! prefix (v3) to a ! suffix (v4): avoid it' },
];

const STRING = /(["'`])((?:\\.|(?!\1)[^\\])*)\1/g;

/** Every forbidden class in a piece of built JavaScript. */
export function findProblems(source) {
  const problems = [];

  for (const match of source.matchAll(STRING)) {
    for (const token of match[2].split(/\s+/)) {
      if (!token) continue;
      // Drop variants such as dark:, hover:, data-[state=open]:.
      const utility = token.replace(/^(?:[^:[\]]*(?:\[[^\]]*\])?[^:[\]]*:)+/, '');
      const rule = RULES.find((r) => r.test.test(utility));

      if (rule && looksLikeClassList(match[2])) {
        problems.push({ token, why: rule.why });
      }
    }
  }

  return problems;
}

// A string counts as a class list when every word looks like a utility:
// lower case (outside [arbitrary values]) and not ending in punctuation.
// This keeps prose, URLs and code strings out of the check.
function looksLikeClassList(text) {
  return text
    .trim()
    .split(/\s+/)
    .every((word) => {
      const bare = word.replace(/\[[^\]]*\]/g, '');

      return /^[a-z0-9!_:/.\-%>&*@]+$/.test(bare) && !/[.,]$/.test(bare);
    });
}
